def art(i=0):
    bg=['#dbe6c9','#d5e3e7','#eadfce','#d9dce8'][i%4]
    color=['#748d49','#4d6b72','#b58a50','#676d91'][i%4]
    return f'''<div class="art"><svg viewBox="0 0 230 290" preserveAspectRatio="xMidYMid slice"><rect width="230" height="290" fill="{bg}"/><circle cx="165" cy="76" r="58" fill="white" opacity=".24"/><ellipse cx="116" cy="234" rx="82" ry="18" fill="{color}" opacity=".19"/><path d="M40 174 L114 126 L193 169 L117 216 Z" fill="{color}"/><path d="M40 174 L117 216 L117 243 L40 201Z" fill="{color}" opacity=".55"/><path d="M117 216 L193 169 L193 195 L117 243Z" fill="{color}" opacity=".8"/><rect x="100" y="111" width="24" height="71" rx="7" fill="#edf2dc"/><circle cx="110" cy="94" r="37" fill="{color}" opacity=".7"/><circle cx="140" cy="118" r="26" fill="{color}"/><circle cx="81" cy="130" r="23" fill="{color}" opacity=".65"/><path d="M38 30L68 30M38 30L38 60M193 260L163 260M193 260L193 230" stroke="white" stroke-width="2" opacity=".7"/></svg><span class="overlay">示意封面 · AI创意</span><span class="duration">00:15</span><span class="play">▷</span></div>'''

def btn(t,kind=''): return f'<button class="btn {kind}">{t}</button>'
def tag(t,kind=''): return f'<span class="tag {kind}">{t}</span>'
def pill(t,selected=False): return f'<span class="pill {"selected" if selected else ""}">{t}</span>'
def kv(k,v):return f'<div class="kv"><span>{k}</span><span>{v}</span></div>'
def head(t,sub='',actions=''):return f'<div class="heading"><div><h1>{t}</h1><div class="sub">{sub}</div></div><div class="row">{actions}</div></div>'
def table(headers,rows):return '<table class="table"><thead><tr>'+''.join(f'<th>{v}</th>' for v in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(f'<td>{v}</td>' for v in r)+'</tr>' for r in rows)+'</tbody></table>'
def stat(labels,values):return '<div class="statgrid">'+''.join(f'<div class="stat"><small>{l}</small><strong>{v}</strong></div>' for l,v in zip(labels,values))+'</div>'
def card(i,saved=False):return f'<div class="card">{art(i)}<div class="cardbody"><div class="cardtitle">{titles[i]}</div><div class="info">{authors[i]} · 粉丝 {fans[i]}<br>2026-09-05 发布</div><div class="data"><span>播放 {views[i]}</span><span>赞 {likes[i]}</span></div><div class="cardfoot"><span>{"★ 已收藏" if saved else "☆ 收藏"}</span><span>一键复刻 →</span></div></div></div>'
def shell(body,admin=False,asset=False,modal=''):
    navs=['候选池','内容审核','过滤规则','每日发布','在架内容','来源账号','效果看板'] if admin else ['灵感发现','UGC爆款','品牌追踪']
    active='候选池' if admin else 'UGC爆款'
    if admin:
        for marker,nav in [('审核内容','内容审核'),('过滤规则与批量处理','过滤规则'),('每日精选编排','每日发布'),('在架内容维护','在架内容'),('推荐来源与供给','来源账号'),('内容与用户效果','效果看板')]:
            if '<h1>'+marker+'</h1>' in body: active=nav
    side='<div class="workspace">▣　Default　⌄</div>'+('<div class="label">内容运营</div>' if admin else '')+''.join(f'<div class="nav {"on" if n==active and not asset else ""}">{n}</div>' for n in navs)
    if not admin: side+='<div class="label">工作空间</div><div class="nav">视频复刻</div><div class="nav '+('on' if asset else '')+'">我的资产</div>'
    return f'<div class="screen"><div class="rail"><b>◈</b><span>⌂</span><span class="lit">♧</span><span>✧</span><span>▧</span></div><aside class="side">{side}</aside><main class="main"><div class="top"><span>{"内容运营 / UGC爆款" if admin else "我的资产 / 收藏" if asset else "灵感发现 / UGC爆款"}</span><span class="muted">CreatiSignal</span></div><div class="content">{body}</div></main>{modal}<div class="specnote">产品示例图片 · 账号、封面和数值均为演示数据</div></div>'

