def inline(t):
    t=html.escape(t)
    return re.sub(r'\*\*(.+?)\*\*',r'<strong>\1</strong>',t)

def md_html(text):
    lines=text.strip().splitlines(); out=[]; i=0
    while i<len(lines):
        l=lines[i].strip()
        if not l:i+=1;continue
        if l.startswith('# '): out.append('<h1>'+inline(l[2:])+'</h1>')
        elif l.startswith('## '):out.append('<h2>'+inline(l[3:])+'</h2>')
        elif l.startswith('!['):
            m=re.match(r'!\[(.*?)\]\((.*?)\)',l)
            p=ROOT/m[2]
            if p.exists():
                data=base64.b64encode(p.read_bytes()).decode()
                out.append('<figure><img src="data:image/png;base64,'+data+'" alt="'+html.escape(m[1])+'"><figcaption>'+html.escape(m[1])+'　静态示例</figcaption></figure>')
        elif l.startswith('|'):
            rows=[]
            while i<len(lines) and lines[i].strip().startswith('|'):
                row=lines[i].strip()
                if not re.match(r'^\|[\s:|-]+\|$',row):rows.append([x.strip() for x in row.strip('|').split('|')])
                i+=1
            out.append('<table><thead><tr>'+''.join('<th>'+inline(c)+'</th>' for c in rows[0])+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+inline(c)+'</td>' for c in r)+'</tr>' for r in rows[1:])+'</tbody></table>');continue
        elif l.startswith('- ') or re.match(r'^\d+\. ',l):
            ordered=bool(re.match(r'^\d+\. ',l)); typ='ol' if ordered else 'ul'; items=[]
            while i<len(lines) and (re.match(r'^\d+\. ',lines[i].strip()) if ordered else lines[i].strip().startswith('- ')):
                val=re.sub(r'^(?:\d+\. |- )','',lines[i].strip());items.append('<li>'+inline(val)+'</li>');i+=1
            out.append('<'+typ+'>'+''.join(items)+'</'+typ+'>');continue
        else:out.append('<p>'+inline(l)+'</p>')
        i+=1
    return '\n'.join(out)

