def build_doc():
    src=ROOT/'UGC爆款_产品需求文档_V1.0.md'
    sections=src.read_text(encoding='utf-8').split('<!-- page -->')
    chunks=[]
    for i,section in enumerate(sections):
        feature='![' in section
        cls='page'+(' feature' if feature else '')+(' tabled' if feature and '|' in section else '')+(' cover' if i==0 else '')+(' dense' if i in [4,20,21,22,23,24,26,27,28,29] else '')
        chunks.append(f'<section class="{cls}" id="page-{i+1}"><header><span>CREATISIGNAL　/　产品需求</span><span>UGC爆款　V1.0</span></header><div class="pagebody">'+md_html(section)+f'</div><footer><span>2026年9月8日　·　产品与研发评审</span><span>{i+1:02d} / {len(sections):02d}</span></footer></section>')
    (BUILD/'document.html').write_text('<!DOCTYPE html><html lang="zh-CN"><meta charset="utf-8"><title>UGC爆款产品需求文档</title><style>'+DOC_STYLE+'</style><body>'+''.join(chunks)+'</body></html>',encoding='utf-8')
    print('pages',len(sections),'screens',len(screens))

if __name__=='__main__':build_doc()
